// KlickTipp subscribe 替身：字段+tag+list 一次写入（语义与模板一致）
const zoom = $input.first().json;
const raw = $('KlickTipp Trigger').item.json;
const trigger = raw.body || raw;
// 模板原表达式 + isNaN 守卫（坑#2 修复）
const unix = Math.floor(new Date(((zoom.occurrences || []).filter(o => o.status !== 'deleted' && new Date(o.start_time) > new Date()).sort((a, b) => new Date(a.start_time) - new Date(b.start_time))[0] || zoom).start_time).getTime() / 1000);
const record = {
  listId: '358895',
  tagId: '12687810',
  email: trigger.email,
  field219991: zoom.join_url,
  field219990: Number.isNaN(unix) ? null : unix
};
// 免费落地：写本地 JSON 档案（生产可换飞书多维表/任意 HTTP CRM）
const fs = require('fs');
const ARCHIVE = '/home/node/.n8n/lesson-16-contacts.json';
let db = [];
try { db = JSON.parse(fs.readFileSync(ARCHIVE, 'utf8')); } catch (e) {}
db.push(record);
fs.writeFileSync(ARCHIVE, JSON.stringify(db, null, 2));
return [{ json: record }];

